<?php
include("auth_owner.php");include("db.php");include("functions.php");$name=full_name($conn,$owner_id,'Owner');
$stats=['items'=>0,'available'=>0,'pending'=>0,'approved'=>0];
$stmt=mysqli_prepare($conn,"SELECT COUNT(*) total,SUM(status='available') available FROM items WHERE owner_id=?");mysqli_stmt_bind_param($stmt,"i",$owner_id);mysqli_stmt_execute($stmt);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if($r){$stats['items']=(int)$r['total'];$stats['available']=(int)$r['available'];}
$stmt=mysqli_prepare($conn,"SELECT SUM(rr.status='pending') pending,SUM(rr.status='approved') approved FROM rental_requests rr JOIN items i ON i.item_id=rr.item_id WHERE i.owner_id=?");mysqli_stmt_bind_param($stmt,"i",$owner_id);mysqli_stmt_execute($stmt);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if($r){$stats['pending']=(int)$r['pending'];$stats['approved']=(int)$r['approved'];}
$stmt=mysqli_prepare($conn,"SELECT rr.request_id,rr.status,rr.start_date,rr.end_date,i.item_name,p.full_name FROM rental_requests rr JOIN items i ON i.item_id=rr.item_id LEFT JOIN user_profiles p ON p.user_id=rr.borrower_id WHERE i.owner_id=? ORDER BY rr.request_id DESC LIMIT 6");mysqli_stmt_bind_param($stmt,"i",$owner_id);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$recent=[];while($x=mysqli_fetch_assoc($res))$recent[]=$x;mysqli_stmt_close($stmt);$current='dashboard';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Owner Dashboard | BorrowBee</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><div class="app-layout"><?php include("owner_sidebar.php"); ?><main class="main-content"><header class="topbar"><div><h1>Welcome, <?php echo e($name); ?> 👋</h1><p class="topbar-sub">Manage your listings and borrower requests.</p></div><a href="add_item.php" class="btn-login btn-inline">+ Add Item</a></header><section class="stat-grid"><div class="stat-card"><b><?php echo $stats['items']; ?></b><span>Total Items</span></div><div class="stat-card"><b><?php echo $stats['available']; ?></b><span>Available</span></div><div class="stat-card"><b><?php echo $stats['pending']; ?></b><span>Pending Requests</span></div><div class="stat-card"><b><?php echo $stats['approved']; ?></b><span>Approved / Active</span></div></section><section class="panel"><div class="panel-heading"><h2>Recent Requests</h2><a href="owner_requests.php">View All</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>ID</th><th>Borrower</th><th>Item</th><th>Dates</th><th>Status</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="5">No requests yet.</td></tr><?php endif;?><?php foreach($recent as $r):?><tr><td>#<?php echo (int)$r['request_id']; ?></td><td><?php echo e($r['full_name']?:'Borrower'); ?></td><td><?php echo e($r['item_name']); ?></td><td><?php echo e($r['start_date']); ?> → <?php echo e($r['end_date']); ?></td><td><span class="status-pill status-<?php echo e($r['status']); ?>"><?php echo e(ucfirst($r['status'])); ?></span></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>
